void MapBasedDetector::routeCallback(
  const autoware_planning_msgs::msg::LaneletRoute::ConstSharedPtr input_msg)
{
  if (!detector_) {
    RCLCPP_WARN(get_logger(), "failed to set traffic lights in route: map not received");
    return;
  }
  auto error = detector_->setRoute(*input_msg);
  if (error) {
    RCLCPP_ERROR(get_logger(), "%s", error->message.c_str());
  }
}

std::optional<SetRouteError> TrafficLightMapBasedDetector::setRoute(
  const autoware_planning_msgs::msg::LaneletRoute & route_msg)
{
  lanelet::ConstLanelets route_lanelets;
  for (const auto & segment : route_msg.segments) {
    for (const auto & primitive : segment.primitives) {
      try {
        route_lanelets.push_back(lanelet_map_ptr_->laneletLayer.get(primitive.id));
      } catch (const lanelet::NoSuchPrimitiveError & ex) {
        return SetRouteError{ex.what()};
      }
    }
  }

  std::vector<lanelet::AutowareTrafficLightConstPtr> route_lanelet_traffic_lights =
    lanelet::utils::query::autowareTrafficLights(route_lanelets);
  route_traffic_lights_ptr_ = std::make_shared<TrafficLightSet>();
  for (auto traffic_light_iter = route_lanelet_traffic_lights.begin();
       traffic_light_iter != route_lanelet_traffic_lights.end(); ++traffic_light_iter) {
    lanelet::AutowareTrafficLightConstPtr traffic_light_reg_elem = *traffic_light_iter;
    auto lights = traffic_light_reg_elem->trafficLights();
    for (auto light_string_primitive : lights) {
      if (!light_string_primitive.isLineString()) {  // traffic lights must be linestrings
        continue;
      }
      route_traffic_lights_ptr_->insert(
        static_cast<lanelet::ConstLineString3d>(light_string_primitive));
    }
  }

  // crosswalk traffic lights
  lanelet::ConstLanelets conflicting_crosswalks;
  pedestrian_traffic_light_id_.clear();

  for (const auto & route_lanelet : route_lanelets) {
    constexpr int PEDESTRIAN_GRAPH_ID = 1;
    const auto conflict_lls =
      overall_graphs_ptr_->conflictingInGraph(route_lanelet, PEDESTRIAN_GRAPH_ID);
    for (const auto & lanelet : conflict_lls) {
      conflicting_crosswalks.push_back(lanelet);
    }
  }
  std::vector<lanelet::AutowareTrafficLightConstPtr> crosswalk_lanelet_traffic_lights =
    lanelet::utils::query::autowareTrafficLights(conflicting_crosswalks);
  for (auto traffic_light_iter = crosswalk_lanelet_traffic_lights.begin();
       traffic_light_iter != crosswalk_lanelet_traffic_lights.end(); ++traffic_light_iter) {
    lanelet::AutowareTrafficLightConstPtr traffic_light_reg_elem = *traffic_light_iter;
    auto lights = traffic_light_reg_elem->trafficLights();
    for (auto light_string_primitive : lights) {
      if (!light_string_primitive.isLineString()) {  // traffic lights must be linestrings
        continue;
      }
      route_traffic_lights_ptr_->insert(
        static_cast<lanelet::ConstLineString3d>(light_string_primitive));
      pedestrian_traffic_light_id_.insert(light_string_primitive.id());
    }
  }

  return std::nullopt;
}

std::vector<lanelet::AutowareTrafficLightConstPtr> autowareTrafficLights(
  const lanelet::ConstLanelets & lanelets)
{
  std::vector<lanelet::AutowareTrafficLightConstPtr> tl_reg_elems;

  for (const auto & ll : lanelets) {
    std::vector<lanelet::AutowareTrafficLightConstPtr> ll_tl_re =
      ll.regulatoryElementsAs<lanelet::autoware::AutowareTrafficLight>();

    // insert unique tl into array
    for (const auto & tl_ptr : ll_tl_re) {
      lanelet::Id id = tl_ptr->id();
      bool unique_id = true;

      for (const auto & tl_reg_elem : tl_reg_elems) {
        if (id == tl_reg_elem->id()) {
          unique_id = false;
          break;
        }
      }

      if (unique_id) {
        tl_reg_elems.push_back(tl_ptr);
      }
    }
  }
  return tl_reg_elems;
}

ConstLanelets conflictingInGraph(const ConstLanelet& lanelet, size_t routingGraphId,
                                 double participantHeight = .0) const {
  if (routingGraphId >= graphs_.size()) {
    throw InvalidInputError("Routing Graph ID is higher than the number of graphs.");
  }
  auto overlaps = [lanelet, participantHeight](const ConstLanelet& ll) {
    return participantHeight != .0 ? !geometry::overlaps3d(lanelet, ll, participantHeight)
                                   : !geometry::overlaps2d(lanelet, ll);
  };
  const auto map{graphs_[routingGraphId]->passableSubmap()};
  ConstLanelets conflicting{map->laneletLayer.search(geometry::boundingBox2d(lanelet))};
  auto begin = conflicting.begin();
  auto end = conflicting.end();
  end = std::remove(begin, end, lanelet);
  end = std::remove_if(begin, end, overlaps);
  conflicting.erase(end, conflicting.end());
  return conflicting;
}

IfLL<Lanelet1T, bool> overlaps3d(const Lanelet1T& lanelet, const Lanelet2T& otherLanelet, double heightTolerance) {
  if (overlaps2d(lanelet, otherLanelet)) {
    auto projPts = projectedPoint3d(lanelet.centerline3d(), otherLanelet.centerline3d());
    return std::abs(projPts.first.z() - projPts.second.z()) < heightTolerance;
  }
  return false;
}

IfLL<Lanelet1T, bool> overlaps2d(const Lanelet1T& lanelet, const Lanelet2T& otherLanelet) {
  if (lanelet.constData() == otherLanelet.constData()) {
    return true;
  }
  // check if lanelets are neighbours (share a border)
  if (lanelet.rightBound() == otherLanelet.leftBound() || lanelet.leftBound() == otherLanelet.rightBound() ||
      lanelet.leftBound().invert() == otherLanelet.leftBound() ||
      lanelet.rightBound().invert() == otherLanelet.rightBound() || follows(lanelet, otherLanelet) ||
      follows(otherLanelet, lanelet) || follows(lanelet.invert(), otherLanelet) ||
      follows(otherLanelet.invert(), lanelet)) {
    return false;
  }
  if (!intersects(boundingBox2d(lanelet), boundingBox2d(otherLanelet))) {
    return false;
  }
  CompoundHybridPolygon2d p1(lanelet.polygon2d());
  CompoundHybridPolygon2d p2(otherLanelet.polygon2d());

#if BOOST_VERSION > 105800
  using Mask = boost::geometry::de9im::static_mask<'T', '*', '*', '*', '*', '*', '*', '*', '*'>;
  return boost::geometry::relate(p1, p2, Mask());
#else
  // boost 1.58 did not officially support "relate"
  using Mask = boost::geometry::detail::relate::static_mask<'T', '*', '*', '*', '*', '*', '*', '*', '*'>;
  return boost::geometry::detail::relate::relate<Mask>(p1, p2);
#endif
}

